"""Notion Guard - governed Notion operations for RailCall.Credentials are resolved only through RailCall's injected vault_get("notion")helper. This module never reads environment variables, credential files, orcommand-line arguments for secrets, and never shells out to curl or any otherexternal process. All Notion HTTPS traffic uses urllib.request with acertifi-backed SSLContext (certificate and hostname verification enabled).Every write command makes exactly one HTTP attempt. If a timeout, connectionfailure, HTTP 5xx response, or unreadable response body prevents confirmation,the handler raises a clear "outcome is unknown" error instead of assumingsuccess or retrying automatically."""from __future__ import annotationsimport jsonimport reimport sslimport urllib.errorimport urllib.parseimport urllib.requestAPI_BASE = "https://api.notion.com/v1"NOTION_VERSION = "2026-03-11"def _build_tls_context():    try:        import certifi    except ImportError as exc:        raise RuntimeError(            "The certifi package is required for verified HTTPS. Install with: python -m pip install certifi"        ) from exc    return ssl.create_default_context(cafile=certifi.where())# Pattern-based redaction layered on top of literal secret substitution, so# a credential leaking through a differently-cased or differently-sourced# string than the exact `secret` value passed in still gets caught: known# Notion integration token shapes (secret_... / ntn_...), Authorization# header values, and NOTION_API_KEY field assignments._NOTION_TOKEN_RE = re.compile(r"(?:secret_|ntn_)[A-Za-z0-9]{20,}")_AUTH_HEADER_RE = re.compile(r"(?i)(authorization\s*[:=]\s*)(?:bearer\s+)?[^\s,;]+")_SECRET_FIELD_RE = re.compile(r"(?i)(NOTION_API_KEY\s*[:=]\s*)[^\s,;]+")_UNSAFE_ID_RE = re.compile(r"[\x00-\x20\x7f]")def _redact(text, secret):    if not isinstance(text, str):        text = str(text)    if secret:        text = text.replace(secret, "[REDACTED]")    text = _NOTION_TOKEN_RE.sub("[REDACTED]", text)    text = _AUTH_HEADER_RE.sub(r"\1[REDACTED]", text)    text = _SECRET_FIELD_RE.sub(r"\1[REDACTED]", text)    return textdef _extract_error_message(raw):    try:        parsed = json.loads(raw)    except (json.JSONDecodeError, TypeError):        return (raw or "no response body")[:300]    if isinstance(parsed, dict):        message = parsed.get("message")        if isinstance(message, str) and message:            code = parsed.get("code")            if isinstance(code, str) and code:                return f"{message} [{code}]"[:300]            return message[:300]    return (raw or "no response body")[:300]def _extract_api_key(entry):    if isinstance(entry, str):        return entry.strip()    if isinstance(entry, dict):        fields = entry.get("fields")        if isinstance(fields, dict):            value = fields.get("NOTION_API_KEY")            if isinstance(value, str):                return value.strip()        # RailCall Station's credential_resolver.resolve() returns the        # bare fields dict directly for named credentials saved through        # Studio Integrations (no "fields" wrapper) - only the legacy        # keys.local.json path and test fixtures use the wrapped shape.        value = entry.get("NOTION_API_KEY")        if isinstance(value, str):            return value.strip()    return ""def _load_api_key():    helpers = globals().get("__rc_helpers__")    if not isinstance(helpers, dict):        raise RuntimeError(            "RailCall's vault_get helper is not available. Configure NOTION_API_KEY in "            "RailCall Studio -> Integrations -> Notion before using Notion Guard."        )    vault_get = helpers.get("vault_get")    if vault_get is None:        raise RuntimeError(            "vault_get helper is not available. Configure NOTION_API_KEY in RailCall "            "Studio -> Integrations -> Notion before using Notion Guard."        )    try:        entry = vault_get("notion")    except Exception as exc:        raise RuntimeError(            "Could not read the Notion credential from RailCall Vault. Configure "            "NOTION_API_KEY in RailCall Studio -> Integrations -> Notion before using "            "Notion Guard."        ) from exc    api_key = _extract_api_key(entry)    if not api_key:        raise RuntimeError(            "Notion credential is not configured. Configure NOTION_API_KEY in RailCall "            "Studio -> Integrations -> Notion before using Notion Guard."        )    return api_keydef _request(method, path, api_key, body=None, query=None, is_write=False):    """Make exactly one HTTPS request to the Notion API. No command is retried here."""    url = API_BASE + path    if query:        clean_query = {k: v for k, v in query.items() if v is not None}        if clean_query:            url = url + "?" + urllib.parse.urlencode(clean_query)    data = json.dumps(body).encode("utf-8") if body is not None else None    request = urllib.request.Request(        url,        data=data,        headers={            "Authorization": f"Bearer {api_key}",            "Notion-Version": NOTION_VERSION,            "Content-Type": "application/json",        },        method=method,    )    context = _build_tls_context()    try:        with urllib.request.urlopen(request, timeout=25, context=context) as response:            status = response.getcode()            raw = response.read().decode("utf-8")    except urllib.error.HTTPError as exc:        status = exc.code        raw = exc.read().decode("utf-8", errors="replace")        if status == 429:            retry_after = exc.headers.get("Retry-After") if exc.headers else None            if isinstance(retry_after, str) and retry_after.strip():                raise RuntimeError(                    f"Notion API rate limit reached. Notion says to wait {retry_after.strip()} seconds "                    "before retrying; Notion Guard never automatically retries a request."                ) from None            raise RuntimeError(                "Notion API rate limit reached. Wait before retrying; Notion Guard "                "never automatically retries a request."            ) from None        if is_write and status >= 500:            raise RuntimeError(                "Notion returned a server error and the write outcome is unknown. "                "Check Notion directly before retrying."            ) from None        message = _extract_error_message(raw)        raise RuntimeError(            _redact(f"Notion API returned HTTP {status}: {message}", api_key)        ) from None    except (urllib.error.URLError, TimeoutError, OSError) as exc:        if is_write:            raise RuntimeError(                "The write request to Notion did not complete and the outcome is "                "unknown. Check Notion directly before retrying."            ) from None        raise RuntimeError(_redact(f"Could not reach Notion: {exc}", api_key)) from None    if not raw:        if is_write:            raise RuntimeError(                "Notion returned an empty response and the write outcome is unknown. "                "Check Notion directly before retrying."            )        return status, {}    try:        parsed = json.loads(raw)    except json.JSONDecodeError:        if is_write:            raise RuntimeError(                "Notion returned an unreadable response and the write outcome is "                "unknown. Check Notion directly before retrying."            ) from None        raise RuntimeError("Notion returned an unreadable response.") from None    if not isinstance(parsed, dict):        raise RuntimeError("Notion returned an unexpected response shape.")    return status, parseddef _require(value, field_name):    if not isinstance(value, str) or not value.strip():        raise RuntimeError(f"{field_name} is required.")    return value.strip()def _require_id(value, field_name):    value = _require(value, field_name)    try:        value.encode("ascii")    except UnicodeEncodeError:        raise RuntimeError(f"{field_name} must contain only ASCII characters, which is not a valid Notion ID.") from None    if _UNSAFE_ID_RE.search(value):        raise RuntimeError(f"{field_name} contains a control character or space, which is not a valid Notion ID.")    if "/" in value or "\\" in value:        raise RuntimeError(f"{field_name} contains a path separator, which is not a valid Notion ID.")    return valuedef _bounded_page_size(value, default=20, maximum=50):    if value is None or value == "":        return default    if isinstance(value, float) and not value.is_integer():        raise RuntimeError("page_size must be an integer.")    try:        parsed = int(value)    except (TypeError, ValueError):        raise RuntimeError("page_size must be an integer.")    if parsed <= 0:        raise RuntimeError("page_size must be a positive integer.")    return min(parsed, maximum)def _parse_json_object(name, raw):    if raw in (None, ""):        return None    try:        value = json.loads(raw)    except json.JSONDecodeError as exc:        raise RuntimeError(f"{name} must be valid JSON: {exc}") from exc    if not isinstance(value, dict):        raise RuntimeError(f"{name} must be a JSON object.")    return valuedef _parse_json_list(name, raw):    if raw in (None, ""):        return None    try:        value = json.loads(raw)    except json.JSONDecodeError as exc:        raise RuntimeError(f"{name} must be valid JSON: {exc}") from exc    if not isinstance(value, list):        raise RuntimeError(f"{name} must be a JSON array.")    return valuedef _simplify_rich_text(items):    if not isinstance(items, list):        return ""    return "".join(        str(item.get("plain_text", "")) for item in items if isinstance(item, dict)    )def _simplify_property(value):    if not isinstance(value, dict):        return None    ptype = value.get("type")    if ptype == "title":        return _simplify_rich_text(value.get("title"))    if ptype == "rich_text":        return _simplify_rich_text(value.get("rich_text"))    if ptype == "select":        select = value.get("select")        return select.get("name") if isinstance(select, dict) else None    if ptype == "status":        status_value = value.get("status")        return status_value.get("name") if isinstance(status_value, dict) else None    if ptype == "multi_select":        items = value.get("multi_select") or []        return [item.get("name") for item in items if isinstance(item, dict)]    if ptype == "date":        date_value = value.get("date")        return date_value if isinstance(date_value, dict) else None    if ptype == "checkbox":        return value.get("checkbox")    if ptype == "number":        return value.get("number")    if ptype == "people":        people = value.get("people") or []        return [p.get("name") or p.get("id") for p in people if isinstance(p, dict)]    if ptype == "relation":        relations = value.get("relation") or []        return [r.get("id") for r in relations if isinstance(r, dict)]    if ptype in ("url", "email", "phone_number", "created_time", "last_edited_time"):        return value.get(ptype)    return Nonedef _simplify_properties(properties):    if not isinstance(properties, dict):        return {}    return {name: _simplify_property(value) for name, value in properties.items()}def _title_from_properties(properties):    if not isinstance(properties, dict):        return ""    for value in properties.values():        if isinstance(value, dict) and value.get("type") == "title":            return _simplify_rich_text(value.get("title"))    return ""def _simplify_block(block):    if not isinstance(block, dict):        return {}    btype = block.get("type")    payload = block.get(btype) if btype else None    text = ""    if isinstance(payload, dict) and isinstance(payload.get("rich_text"), list):        text = _simplify_rich_text(payload.get("rich_text"))    return {        "id": block.get("id"),        "type": btype,        "text": text,        "has_children": bool(block.get("has_children")),    }def notion_search(inputs, stamp):    """Search pages and data sources shared with the connection."""    query = inputs.get("query")    object_type = inputs.get("object_type")    if object_type not in (None, "", "page", "data_source"):        raise RuntimeError("object_type must be 'page' or 'data_source' when provided.")    page_size = _bounded_page_size(inputs.get("page_size"))    body = {"page_size": page_size}    if isinstance(query, str) and query.strip():        body["query"] = query.strip()    if object_type:        body["filter"] = {"value": object_type, "property": "object"}    start_cursor = inputs.get("start_cursor")    if isinstance(start_cursor, str) and start_cursor.strip():        body["start_cursor"] = start_cursor.strip()    api_key = _load_api_key()    status, data = _request("POST", "/search", api_key, body=body)    results = data.get("results")    if not isinstance(results, list):        raise RuntimeError("Notion did not return a results list for search.")    simplified = []    for item in results:        if not isinstance(item, dict):            continue        object_kind = item.get("object")        if object_kind == "page":            title = _title_from_properties(item.get("properties"))        elif object_kind == "data_source":            title = _simplify_rich_text(item.get("title"))        else:            title = ""        simplified.append(            {                "id": item.get("id"),                "object": object_kind,                "title": title,                "url": item.get("url"),            }        )    return {        "ok": True,        "http_status": status,        "returned_count": len(simplified),        "results_json": json.dumps(simplified, ensure_ascii=False),        "next_cursor": data.get("next_cursor"),        "has_more": bool(data.get("has_more")),    }, Nonedef notion_get_data_source_schema(inputs, stamp):    """Retrieve a data source's property schema so writes target real field names.    Accepts either data_source_id directly, or database_id (e.g. copied from    a Notion database URL) to resolve it automatically. Most databases have    exactly one data source; if a database has more than one, this raises a    clear error listing them instead of guessing which one was meant.    """    data_source_id = inputs.get("data_source_id")    database_id = inputs.get("database_id")    if not (isinstance(data_source_id, str) and data_source_id.strip()) and not (        isinstance(database_id, str) and database_id.strip()    ):        raise RuntimeError("Provide data_source_id or database_id.")    api_key = _load_api_key()    if not (isinstance(data_source_id, str) and data_source_id.strip()):        database_id = _require_id(database_id, "database_id")        db_status, db_data = _request("GET", f"/databases/{database_id}", api_key)        data_sources = db_data.get("data_sources")        if not isinstance(data_sources, list) or not data_sources:            raise RuntimeError("Notion did not return any data sources for this database.")        if len(data_sources) > 1:            ids = ", ".join(                str(ds.get("id")) for ds in data_sources if isinstance(ds, dict)            )            raise RuntimeError(                f"This database has {len(data_sources)} data sources; pass one "                f"explicitly via data_source_id: {ids}"            )        first_data_source = data_sources[0]        if not isinstance(first_data_source, dict):            raise RuntimeError("Notion returned a malformed data source entry for this database.")        data_source_id = first_data_source.get("id")    data_source_id = _require_id(data_source_id, "data_source_id")    status, data = _request("GET", f"/data_sources/{data_source_id}", api_key)    properties = data.get("properties")    if not isinstance(properties, dict):        raise RuntimeError("Notion did not return a properties schema for this data source.")    simplified = {}    for name, definition in properties.items():        if not isinstance(definition, dict):            continue        ptype = definition.get("type")        entry = {"type": ptype, "id": definition.get("id")}        options_holder = definition.get(ptype) if ptype else None        if isinstance(options_holder, dict) and isinstance(options_holder.get("options"), list):            entry["options"] = [                option.get("name")                for option in options_holder["options"]                if isinstance(option, dict)            ]        simplified[name] = entry    return {        "ok": True,        "http_status": status,        "data_source_id": data.get("id"),        "title": _simplify_rich_text(data.get("title")),        "property_count": len(simplified),        "properties_json": json.dumps(simplified, ensure_ascii=False),    }, Nonedef notion_query_data_source(inputs, stamp):    """List/filter/sort the rows (pages) belonging to a data source."""    data_source_id = _require_id(inputs.get("data_source_id"), "data_source_id")    filter_obj = _parse_json_object("filter_json", inputs.get("filter_json"))    sorts_obj = _parse_json_list("sorts_json", inputs.get("sorts_json"))    page_size = _bounded_page_size(inputs.get("page_size"))    body = {"page_size": page_size}    if filter_obj is not None:        body["filter"] = filter_obj    if sorts_obj is not None:        body["sorts"] = sorts_obj    start_cursor = inputs.get("start_cursor")    if isinstance(start_cursor, str) and start_cursor.strip():        body["start_cursor"] = start_cursor.strip()    api_key = _load_api_key()    status, data = _request(        "POST", f"/data_sources/{data_source_id}/query", api_key, body=body    )    results = data.get("results")    if not isinstance(results, list):        raise RuntimeError("Notion did not return a results list for this query.")    simplified = []    for item in results:        if not isinstance(item, dict):            continue        simplified.append(            {                "id": item.get("id"),                "url": item.get("url"),                "in_trash": bool(item.get("in_trash")),                "properties": _simplify_properties(item.get("properties")),            }        )    return {        "ok": True,        "http_status": status,        "data_source_id": data_source_id,        "returned_count": len(simplified),        "results_json": json.dumps(simplified, ensure_ascii=False),        "next_cursor": data.get("next_cursor"),        "has_more": bool(data.get("has_more")),    }, Nonedef notion_get_page(inputs, stamp):    """Retrieve one page's properties."""    page_id = _require_id(inputs.get("page_id"), "page_id")    api_key = _load_api_key()    status, data = _request("GET", f"/pages/{page_id}", api_key)    return {        "ok": True,        "http_status": status,        "page_id": data.get("id"),        "url": data.get("url"),        "in_trash": bool(data.get("in_trash")),        "parent_json": json.dumps(data.get("parent") or {}, ensure_ascii=False),        "properties_json": json.dumps(            _simplify_properties(data.get("properties")), ensure_ascii=False        ),        "created_time": data.get("created_time"),        "last_edited_time": data.get("last_edited_time"),    }, Nonedef notion_get_page_content(inputs, stamp):    """Retrieve the first level of a page's or block's content.    page_id and block_id are interchangeable inputs: Notion's own API reads    children from any block, and a page is itself a block for this purpose.    Pass page_id for a page's top-level content, or block_id to read the    children of one specific nested block (e.g. a toggle) returned by an    earlier call to this same command.    """    block_id = _require_id(inputs.get("page_id") or inputs.get("block_id"), "page_id or block_id")    page_size = _bounded_page_size(inputs.get("page_size"))    query = {"page_size": page_size}    start_cursor = inputs.get("start_cursor")    if isinstance(start_cursor, str) and start_cursor.strip():        query["start_cursor"] = start_cursor.strip()    api_key = _load_api_key()    status, data = _request("GET", f"/blocks/{block_id}/children", api_key, query=query)    results = data.get("results")    if not isinstance(results, list):        raise RuntimeError("Notion did not return block children.")    simplified = [_simplify_block(block) for block in results if isinstance(block, dict)]    return {        "ok": True,        "http_status": status,        "block_id": block_id,        "returned_count": len(simplified),        "blocks_json": json.dumps(simplified, ensure_ascii=False),        "next_cursor": data.get("next_cursor"),        "has_more": bool(data.get("has_more")),    }, Nonedef notion_list_users(inputs, stamp):    """List workspace users so writes can address teammates by name, not raw IDs."""    page_size = _bounded_page_size(inputs.get("page_size"))    query = {"page_size": page_size}    start_cursor = inputs.get("start_cursor")    if isinstance(start_cursor, str) and start_cursor.strip():        query["start_cursor"] = start_cursor.strip()    api_key = _load_api_key()    status, data = _request("GET", "/users", api_key, query=query)    results = data.get("results")    if not isinstance(results, list):        raise RuntimeError("Notion did not return a users list.")    simplified = []    for item in results:        if not isinstance(item, dict):            continue        entry = {"id": item.get("id"), "name": item.get("name"), "type": item.get("type")}        person = item.get("person")        if isinstance(person, dict) and person.get("email"):            entry["email"] = person.get("email")        simplified.append(entry)    return {        "ok": True,        "http_status": status,        "returned_count": len(simplified),        "users_json": json.dumps(simplified, ensure_ascii=False),        "next_cursor": data.get("next_cursor"),        "has_more": bool(data.get("has_more")),    }, Nonedef notion_create_page(inputs, stamp):    """Create a new page (e.g. a task/row) under a data source or a parent page."""    parent_type = inputs.get("parent_type")    if parent_type not in ("data_source_id", "page_id"):        raise RuntimeError("parent_type must be 'data_source_id' or 'page_id'.")    parent_id = _require_id(inputs.get("parent_id"), "parent_id")    properties = _parse_json_object("properties_json", inputs.get("properties_json"))    if properties is None:        raise RuntimeError("properties_json is required and must be a JSON object.")    children = _parse_json_list("children_json", inputs.get("children_json"))    if children is not None and len(children) > 100:        raise RuntimeError("children_json may contain at most 100 blocks per request.")    icon_emoji = inputs.get("icon_emoji")    body = {        "parent": {"type": parent_type, parent_type: parent_id},        "properties": properties,    }    if children is not None:        body["children"] = children    if isinstance(icon_emoji, str) and icon_emoji.strip():        body["icon"] = {"type": "emoji", "emoji": icon_emoji.strip()}    api_key = _load_api_key()    status, data = _request("POST", "/pages", api_key, body=body, is_write=True)    return {        "ok": True,        "http_status": status,        "page_id": data.get("id"),        "url": data.get("url"),        "parent_json": json.dumps(data.get("parent") or {}, ensure_ascii=False),        "properties_json": json.dumps(            _simplify_properties(data.get("properties")), ensure_ascii=False        ),        "created_time": data.get("created_time"),    }, Nonedef notion_update_page_properties(inputs, stamp):    """Update a page's properties, and/or move it to/from the trash."""    page_id = _require_id(inputs.get("page_id"), "page_id")    properties = _parse_json_object("properties_json", inputs.get("properties_json"))    in_trash = inputs.get("in_trash")    if properties is None and in_trash is None:        raise RuntimeError("Provide at least one of properties_json or in_trash to update.")    body = {}    if properties is not None:        body["properties"] = properties    if in_trash is not None:        body["in_trash"] = bool(in_trash)    api_key = _load_api_key()    status, data = _request("PATCH", f"/pages/{page_id}", api_key, body=body, is_write=True)    return {        "ok": True,        "http_status": status,        "page_id": data.get("id"),        "url": data.get("url"),        "in_trash": bool(data.get("in_trash")),        "properties_json": json.dumps(            _simplify_properties(data.get("properties")), ensure_ascii=False        ),        "last_edited_time": data.get("last_edited_time"),    }, Nonedef notion_append_blocks(inputs, stamp):    """Append content blocks (notes, checklists, updates) to an existing page or block."""    block_id = _require_id(inputs.get("block_id"), "block_id")    children = _parse_json_list("children_json", inputs.get("children_json"))    if not children:        raise RuntimeError(            "children_json is required and must be a non-empty JSON array of block objects."        )    if len(children) > 100:        raise RuntimeError("children_json may contain at most 100 blocks per request.")    position = inputs.get("position") or "end"    if position not in ("end", "start"):        raise RuntimeError("position must be 'end' or 'start'.")    body = {"children": children, "position": {"type": position}}    api_key = _load_api_key()    status, data = _request(        "PATCH", f"/blocks/{block_id}/children", api_key, body=body, is_write=True    )    results = data.get("results")    simplified = (        [_simplify_block(block) for block in results if isinstance(block, dict)]        if isinstance(results, list)        else []    )    return {        "ok": True,        "http_status": status,        "block_id": block_id,        "appended_count": len(simplified),        "blocks_json": json.dumps(simplified, ensure_ascii=False),    }, Nonedef notion_create_comment(inputs, stamp):    """Add a comment to a page/block, or reply to an existing discussion thread."""    parent_type = inputs.get("parent_type")    if parent_type not in ("page_id", "block_id", "discussion_id"):        raise RuntimeError("parent_type must be 'page_id', 'block_id', or 'discussion_id'.")    parent_id = _require_id(inputs.get("parent_id"), "parent_id")    text = inputs.get("text")    if not isinstance(text, str) or not text.strip():        raise RuntimeError("text is required and must be non-empty.")    if len(text) > 2000:        raise RuntimeError("text must be at most 2000 characters.")    body = {"rich_text": [{"text": {"content": text}}]}    if parent_type == "discussion_id":        body["discussion_id"] = parent_id    else:        body["parent"] = {parent_type: parent_id}    api_key = _load_api_key()    status, data = _request("POST", "/comments", api_key, body=body, is_write=True)    return {        "ok": True,        "http_status": status,        "comment_id": data.get("id"),        "discussion_id": data.get("discussion_id"),        "parent_json": json.dumps(data.get("parent") or {}, ensure_ascii=False),        "created_time": data.get("created_time"),    }, None